#!/usr/bin/env python3
"""Pack data/level11_*.txt into a compact binary + a C include (generated, do not edit).  usage: pack_data.py data out.bin out.inc"""
import struct, sys
d, outb, outi = sys.argv[1:4]
tris = []; pk = []
for l in open(d + '/level11_solids.txt'):
    if l[0] == '#': continue
    f = l.split()
    if len(f) != 11: continue
    tris.append((ord(f[0]), int(f[1]), [float(x) for x in f[2:]]))
for l in open(d + '/level11_pockets.txt'):
    if l[0] == '#': continue
    f = l.split()
    if len(f) != 7: continue
    pk.append((f[0], [float(x) for x in f[1:]]))
hulls = []
import os
if os.path.exists(d + '/level11_pocket_hulls.txt'):
    for l in open(d + '/level11_pocket_hulls.txt'):
        if l[0] == '#': continue
        f = l.split()
        if len(f) < 2: continue
        k = int(f[1]); v = [float(x) for x in f[2:2 + 2 * k]]
        if len(v) == 2 * k: hulls.append((f[0], v))
b = bytearray(b'PP2D' + struct.pack('<II', len(tris), len(pk)))
for m, ly, v in tris: b += struct.pack('<BB9d', m, ly, *v)
for n, v in pk: b += n.encode()[:16].ljust(16, b'\0') + struct.pack('<6d', *v)
if hulls:
    b += b'HULL' + struct.pack('<I', len(hulls))
    for n, v in hulls: b += n.encode()[:16].ljust(16, b'\0') + struct.pack('<I', len(v) // 2) + struct.pack('<%dd' % len(v), *v)
# P2X: optional 3D hull section: 'HUL3' u32 n | n x { char[16] name, u32 ntri, ntri x 9 f64 }  (after the HULL section)
h3 = []
if os.path.exists(d + '/level11_pocket_hull3d.txt'):
    for l in open(d + '/level11_pocket_hull3d.txt'):
        if l[0] == '#': continue
        f = l.split()
        if len(f) < 2: continue
        k = int(f[1]); v = [float(x) for x in f[2:2 + 9 * k]]
        if len(v) == 9 * k: h3.append((f[0], v))
if h3:
    b += b'HUL3' + struct.pack('<I', len(h3))
    for n, v in h3: b += n.encode()[:16].ljust(16, b'\0') + struct.pack('<I', len(v) // 9) + struct.pack('<%dd' % len(v), *v)
open(outb, 'wb').write(b)
with open(outi, 'w') as f:
    f.write('// generated by tools/pack_data.py from the game files (Level 11); %d triangles, %d pockets\nstatic const unsigned char PP2_DATA[] = {\n' % (len(tris), len(pk)))
    for i in range(0, len(b), 24): f.write(','.join(str(x) for x in b[i:i+24]) + ',\n')
    f.write('};\nstatic const unsigned long PP2_DATA_LEN = %d;\n' % len(b))
print(len(tris), len(pk), len(b))
